import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Core Package Patterns","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/core.md","filePath":"develop/core.md","lastUpdated":null}'),r={name:"develop/core.md"};function i(l,e,n,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/core.md" target="_blank" rel="noreferrer"><code>.agents/core.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="core-package-patterns" tabindex="-1">Core Package Patterns <a class="header-anchor" href="#core-package-patterns" aria-label="Permalink to &quot;Core Package Patterns&quot;">​</a></h1><p>Use this when adding or refactoring shared domain logic in <code>packages/core</code>.</p><p>This file is the source of truth for what belongs in <code>packages/core</code>, how to structure it, and how shared contract changes should propagate through the repo.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Keep shared domain contracts in one place.</li><li>Make API and frontend behavior follow shared changes by import, not by parallel manual edits.</li><li>Keep <code>packages/core</code> runtime-agnostic and safe to consume from <code>packages/auth</code>, <code>packages/db</code>, <code>packages/api</code>, <code>apps/web</code>, and <code>apps/server</code>.</li></ul><h2 id="what-belongs-in-packages-core" tabindex="-1">What Belongs In <code>packages/core</code> <a class="header-anchor" href="#what-belongs-in-packages-core" aria-label="Permalink to &quot;What Belongs In `packages/core`&quot;">​</a></h2><p>Put code in <code>packages/core</code> when at least one of these is true:</p><ul><li>The same domain contract is consumed by more than one package.</li><li>A change should propagate automatically from shared logic into both API and frontend behavior.</li><li>The code defines a shared constant, enum, filter, status, category, transport shape, normalizer, formatter, or option builder.</li><li>The code is pure domain logic with no React, DB, env, logger, or network dependency.</li></ul><p>Typical examples:</p><ul><li>Zod schemas and inferred types for shared transport-safe shapes.</li><li>Shared enums such as categories, statuses, and sort values.</li><li>Pure formatters and normalizers.</li><li>Schema-derived option arrays and defaults used by filters, tabs, selects, or validators.</li><li>Shared constants such as MIME types, upload limits, reserved values, or other package-agnostic constraints.</li></ul><h2 id="what-does-not-belong-in-packages-core" tabindex="-1">What Does Not Belong In <code>packages/core</code> <a class="header-anchor" href="#what-does-not-belong-in-packages-core" aria-label="Permalink to &quot;What Does Not Belong In `packages/core`&quot;">​</a></h2><ul><li>React components, hooks, route files, or TanStack Query wrappers.</li><li>oRPC procedures, router handlers, or request middleware.</li><li>Drizzle schema, SQL queries, migrations, or database access.</li><li>Env loading, logger setup, storage clients, or other side-effectful integrations.</li><li>One-off app-only view logic unless the task explicitly calls for divergence from the shared contract.</li><li>One-off utilities or library functions that are not derived from or directly related to the shared contract, they should be placed within their respective package or slice.</li></ul><h2 id="shared-security-limits" tabindex="-1">Shared Security Limits <a class="header-anchor" href="#shared-security-limits" aria-label="Permalink to &quot;Shared Security Limits&quot;">​</a></h2><p>Keep cross-transport limits and pure validation policy under <code>packages/core/src/security/</code>; keep request readers and provider clients in their runtime owners.</p><ul><li>Default JSON/RPC bodies are bounded before parsing by <code>apps/server</code>.</li><li>Stripe raw webhook bodies are capped at 1 MiB before signature verification.</li><li>Browser log ingestion is capped at 64 KiB plus batch/depth/string limits in <code>packages/logger</code>.</li><li>Media contracts cap general uploads at 8 MB and avatars at 2 MB; the local upload route streams only to the row-specific maximum.</li><li>Outbound webhook policy allows HTTP/HTTPS on ports 80/443, rejects private/reserved addresses, pins validated DNS answers, revalidates redirects, and enforces connect/header/body/total limits.</li></ul><p>Do not duplicate these numbers in routers or UI. Import the shared constants, and add behavior tests at both the pure policy and runtime boundary when changing them.</p><h2 id="default-folder-shape" tabindex="-1">Default Folder Shape <a class="header-anchor" href="#default-folder-shape" aria-label="Permalink to &quot;Default Folder Shape&quot;">​</a></h2><p>Shared domain modules in <code>packages/core</code> should usually look like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/&lt;domain&gt;/</span></span>\n<span class="line"><span>  constants.ts</span></span>\n<span class="line"><span>  types.ts</span></span>\n<span class="line"><span>  utils.ts</span></span>\n<span class="line"><span>  index.ts</span></span></code></pre></div><h3 id="constants-ts" tabindex="-1"><code>constants.ts</code> <a class="header-anchor" href="#constants-ts" aria-label="Permalink to &quot;`constants.ts`&quot;">​</a></h3><p>Use this for support constants that back the domain but are not themselves the primary cross-package contract.</p><p>Examples:</p><ul><li>MIME type lists</li><li>byte limits</li><li>reserved values</li><li>expiry durations</li></ul><p>If the value is a shared contract that API and frontend validate against, it usually belongs in <code>types.ts</code> as a Zod schema instead.</p><h3 id="types-ts" tabindex="-1"><code>types.ts</code> <a class="header-anchor" href="#types-ts" aria-label="Permalink to &quot;`types.ts`&quot;">​</a></h3><p>Use this for shared Zod schemas and inferred types.</p><ul><li>Put cross-layer enums here, even when they are simple literal sets.</li><li>Export both the schema and the inferred type as named exports.</li><li>Export schema-derived defaults here when they are part of the shared contract surface.</li><li>Prefer one shared schema over duplicated literal unions in consumers.</li></ul><h3 id="utils-ts" tabindex="-1"><code>utils.ts</code> <a class="header-anchor" href="#utils-ts" aria-label="Permalink to &quot;`utils.ts`&quot;">​</a></h3><p>Use this for pure helpers derived from the shared contract.</p><ul><li>formatters</li><li>normalizers</li><li>schema-derived option arrays</li><li>shared defaulting helpers</li></ul><p>Prefer deriving labels and UI options from shared schema values instead of introducing parallel frontend arrays or label unions.</p><h3 id="index-ts" tabindex="-1"><code>index.ts</code> <a class="header-anchor" href="#index-ts" aria-label="Permalink to &quot;`index.ts`&quot;">​</a></h3><p>Keep a small domain barrel that re-exports the public API for that domain.</p><p>Consumers should import the domain surface, not deep internal files.</p><h2 id="propagation-rule" tabindex="-1">Propagation Rule <a class="header-anchor" href="#propagation-rule" aria-label="Permalink to &quot;Propagation Rule&quot;">​</a></h2><p>Unless explicitly told not to, shared domain enums and validation logic should propagate from <code>packages/core</code> into both the frontend and API.</p><p>That means:</p><ul><li><code>apps/web</code> route validators should import shared schemas and defaults from core instead of repeating <code>z.enum([...])</code> literals.</li><li>Frontend filters, tabs, and select options should use core-derived helpers or schema values, not duplicated local arrays.</li><li><code>packages/api</code> procedures should validate shared inputs and outputs with core schemas when the contract crosses package boundaries.</li><li>Slice query modules in <code>apps/web</code> may re-export shared types for convenience, but they should not redefine local literal unions if core already owns the contract.</li></ul><p>If adding one enum value requires hand-editing multiple literal unions in <code>apps/web</code> or <code>packages/api</code>, the contract probably belongs in <code>packages/core</code>.</p><h2 id="design-rules" tabindex="-1">Design Rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to &quot;Design Rules&quot;">​</a></h2><ul><li>Keep exports domain-specific and explicit.</li><li>Keep helpers deterministic and side-effect free.</li><li>Favor transport-safe primitives at the package boundary.</li><li>Prefer a formatter or option builder over separate label schemas.</li><li>Prefer names like <code>formatX</code>, <code>normalizeX</code>, <code>getXBase</code> over vague generic helper function names.</li><li>Prefer SCREAMING_SNAKE_CASE for shared constant values and PascalCase for shared enums.</li><li>Zod schemas should be named like <code>const ObjectSchema</code> and inferred types should be named like <code>type ObjectType = z.infer&lt;typeof ObjectSchema&gt;</code>.</li><li>For input and output shapes that are shared between API and frontend, prefer naming them like <code>ObjectCreateInputSchema</code> and <code>ObjectUpdateNameInputSchema</code> to clarify their transport role.</li><li>Keep each domain isolated under its own subpath.</li></ul><h2 id="when-to-extract-into-core" tabindex="-1">When To Extract Into Core <a class="header-anchor" href="#when-to-extract-into-core" aria-label="Permalink to &quot;When To Extract Into Core&quot;">​</a></h2><p>Move logic into <code>packages/core</code> when:</p><ul><li>the same domain shape is needed by both <code>packages/api</code> and <code>apps/web</code></li><li><code>packages/auth</code> and <code>packages/api</code> share the same normalization or validation rule</li><li>a shared enum, default, or format should drive frontend behavior automatically</li></ul><p>Keep logic local when it is truly slice-specific, UI-only, router-only, or persistence-only.</p><h2 id="introducing-a-new-shared-enum-or-contract" tabindex="-1">Introducing A New Shared Enum Or Contract <a class="header-anchor" href="#introducing-a-new-shared-enum-or-contract" aria-label="Permalink to &quot;Introducing A New Shared Enum Or Contract&quot;">​</a></h2><p>When you add a new shared category, status, or contract:</p><ol><li>Add or update the schema in <code>packages/core/src/&lt;domain&gt;/types.ts</code>.</li><li>Update any derived helpers in <code>packages/core/src/&lt;domain&gt;/utils.ts</code>.</li><li>Make <code>apps/web</code> consume the shared schema, defaults, and options instead of duplicating literals.</li><li>Make <code>packages/api</code> consume the shared contract instead of redefining parallel schemas.</li><li>Update persisted enums in <code>packages/db</code> and generate a migration if the value is stored in the database.</li></ol><p>This is the default repo behavior unless the task explicitly asks for package-local divergence.</p>',50)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
